def solve(inputs: dict) -> float:
    # Find remainders and moduli lists in inputs
    rem = None
    mod = None
    for k, v in inputs.items():
        if isinstance(v, (list, tuple)):
            lk = k.lower()
            if 'rem' in lk or 'residue' in lk or 'a' == lk:
                rem = list(v)
            elif 'mod' in lk or 'n' == lk:
                mod = list(v)
    # Fallback: assume two lists, first remainders second moduli
    if rem is None or mod is None:
        lists = [v for v in inputs.values() if isinstance(v, (list, tuple))]
        if len(lists) >= 2:
            rem = list(lists[0])
            mod = list(lists[1])
    # CRT
    x = 0
    M = 1
    for m in mod:
        M *= m
    for r, m in zip(rem, mod):
        Mi = M // m
        # modular inverse of Mi mod m
        inv = pow(Mi, -1, m)
        x = (x + r * Mi * inv) % M
    return float(x % M)

