def solve(inputs: dict) -> float:
    M = None
    power = None
    modulus = None
    for k, v in inputs.items():
        lk = k.lower()
        if isinstance(v, (list, tuple)) and len(v) > 0 and isinstance(v[0], (list, tuple)):
            M = [list(row) for row in v]
        elif 'mod' in lk:
            modulus = int(v)
        elif 'pow' in lk or 'exp' in lk or lk in ('n', 'k', 'p'):
            power = int(v)
    # fallback for scalars
    scalars = [(k, v) for k, v in inputs.items() if isinstance(v, (int, float))]
    if power is None or modulus is None:
        # guess: larger is modulus, smaller is power
        vals = sorted([int(v) for k, v in scalars], reverse=True)
        if modulus is None and vals:
            modulus = vals[0]
        if power is None and len(vals) > 1:
            power = vals[1]

    n = len(M)
    def matmul(A, B):
        return [[sum(A[i][k] * B[k][j] for k in range(n)) % modulus for j in range(n)] for i in range(n)]
    # identity
    R = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    base = [[M[i][j] % modulus for j in range(n)] for i in range(n)]
    e = power
    while e > 0:
        if e & 1:
            R = matmul(R, base)
        base = matmul(base, base)
        e >>= 1
    total = sum(R[i][j] for i in range(n) for j in range(n))
    return float(total % modulus)

